def reward_solution_tag_integrity(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']

        # Check for <solution> tag
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if sol_match is None:
            # Check if it's just thinking without solution
            if '<thinking>' in response and '</thinking>' in response:
                scores.append(-0.5) # Has thinking but no final answer
            else:
                scores.append(-1.0) # No structure at all
            continue

        pred = sol_match.group(1).strip()

        # Check if the solution content is empty or just whitespace
        if not pred or not pred.strip():
            scores.append(-1.0)
            continue

        # Check if the solution is just a number or simple expression
        # (This is a heuristic for 'clean' answers)
        if is_correct(pred, true_answer):
            scores.append(3.0)
        else:
            # Check if it's at least a plausible mathematical expression
            if re.search(r'[\d\+\-\*/\^\(\)\s\,\.\frac\sqrt]', pred):
                scores.append(0.5)
            else:
                scores.append(-0.5)
    return scores

def reward_numeric_precision(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if sol_match is None:
            scores.append(-1.0)
            continue

        pred = sol_match.group(1).strip()

        # Try to extract a number from the prediction
        num_match = re.search(r'[-+]?\d*\.?\d+', pred)
        if num_match is None:
            scores.append(0.0) # Not a simple number, skip precision check
            continue

        try:
            pred_val = float(num_match.group(0))
        except:
            scores.append(0.0)
            continue

        # Try to extract a number from the ground truth
        gt_match = re.search(r'[-+]?\d*\.?\d+', true_answer)
        if gt_match is None:
            scores.append(0.0)
            continue

        try:
            gt_val = float(gt_match.group(0))
        except:
            scores.append(0.0)
            continue

        # Calculate relative error
        if gt_val == 0:
            if pred_val == 0:
                scores.append(3.0)
            else:
                scores.append(-1.0)
        else:
            rel_err = abs(pred_val - gt_val) / abs(gt_val)
            if rel_err < 0.01:
                scores.append(3.0)
            elif rel_err < 0.1:
                scores.append(1.0)
            elif rel_err < 0.5:
                scores.append(0.0)
            else:
                scores.append(-1.0)
    return scores

def reward_no_common_mistakes(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']

        # Check for common mathematical mistakes
        # 1. Forgetting to simplify radicals
        if re.search(r'\\sqrt\{\d+\d+\}', response) and not re.search(r'\\sqrt\{\d+\}', response):
            # This is a heuristic; check if the radical could be simplified
            pass

        # 2. Confusing area and perimeter
        if 'area' in response.lower() and 'perimeter' in response.lower():
            # Check if the model is confusing the two
            if re.search(r'area.*?perimeter|perimeter.*?area', response, re.IGNORECASE):
                scores.append(-0.5)
                continue

        # 3. Incorrect use of formulas
        if 'pythagorean' in response.lower() and not re.search(r'a\^2\s*\+\s*b\^2\s*=\s*c\^2|a^2\s*\+\s*b^2\s*=\s*c^2', response):
            scores.append(-0.5)
            continue

        # 4. Not checking the answer
        if 'check' not in response.lower() and 'verify' not in response.lower():
            scores.append(0.0)
        else:
            scores.append(1.0)
    return scores

